import { MakeLogicType, connect, kea, path, selectors } from 'kea'
import { router } from 'kea-router'

import { movedMessagingTabsLogic } from '../Audience/movedMessagingTabsLogic'
import { MESSAGING_NAV_TAB_KEYS, MessagingNavTabKey } from '../messagingTabs'

export type BroadcastsSceneTab = MessagingNavTabKey | 'broadcasts'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface broadcastsSceneLogicValues {
    currentTab: BroadcastsSceneTab
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface broadcastsSceneLogicActions {}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface broadcastsSceneLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        currentTab: (location: { pathname: string; search: string; hash: string }) => BroadcastsSceneTab
    }
}

export type broadcastsSceneLogicType = MakeLogicType<
    broadcastsSceneLogicValues,
    broadcastsSceneLogicActions,
    Record<string, any>,
    broadcastsSceneLogicMeta
>

function isMessagingNavTabKey(segment: string): segment is MessagingNavTabKey {
    return (MESSAGING_NAV_TAB_KEYS as readonly string[]).includes(segment)
}

export const broadcastsSceneLogic = kea<broadcastsSceneLogicType>([
    path(['products', 'workflows', 'frontend', 'Broadcasts', 'broadcastsSceneLogic']),
    connect(() => ({
        logic: [movedMessagingTabsLogic],
    })),
    selectors({
        currentTab: [
            () => [router.selectors.location],
            // The tab routes are literal paths, so the tab is the last path segment rather than a route param.
            ({ pathname }): BroadcastsSceneTab => {
                const lastSegment = pathname.split('/').pop() ?? ''
                return isMessagingNavTabKey(lastSegment) ? lastSegment : 'broadcasts'
            },
        ],
    }),
])
